using ghidra.graph;
using ghidra.graph;

public class JungDirectedGraph<V, E> : DirectedSparseGraph<V, E>, GDirectedGraph<V, E> where E : GEdge<V> {

	/* @Override */
	public void addEdge(E e) {
		base.addEdge(e, e.getStart(), e.getEnd());
	}

	/* @Override */
	public void removeVertices(Iterable<V> toRemove) {
		toRemove.forEach(v => base.removeVertex(v));
	}

	/* @Override */
	public void removeEdges(Iterable<E> toRemove) {
		toRemove.forEach(e => base.removeEdge(e));
	}

	/* @Override */
