		return newGraph;
	}

	/* @Override */
	public GDirectedGraph<V, E> copy() {
		JungDirectedGraph<V, E> newGraph = new();

		foreach (V v in vertices.keySet()) {
			newGraph.addVertex(v);
		}

		foreach (E e in edges.keySet()) {
			newGraph.addEdge(e);
		}

		return newGraph;
	}

	/* @Override */
	public bool isEmpty() {
		return getVertexCount() == 0;
	}
